<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$v=static fn(string $k):string=>$e($values[$k]??'');$error=static function(string $k)use($errors,$e):void{if(isset($errors[$k]))echo '<span class="field-error">'.$e($errors[$k]).'</span>';}; ?>
<div class="page-heading"><div><h1><?= $title==='Create product'?'Dodaj proizvod':'Izmeni proizvod' ?></h1><p>Unesite osnovne podatke o klima uređaju.</p></div><a href="/admin/products">Nazad na proizvode</a></div><?php if($flash):?><p class="flash flash-<?= $e($flash['type']) ?>" role="status"><?= $e($flash['message']) ?></p><?php endif;?><?php if($errors):?><div class="flash flash-error" role="alert"><strong>Ispravite označena polja.</strong></div><?php endif;?>
<form class="admin-form" method="post" action="<?= $e($action) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><section class="panel"><h2>Podaci o proizvodu</h2><div class="form-grid"><label class="wide">Naziv proizvoda<input name="name" value="<?= $v('name') ?>" maxlength="255" required><?php $error('name');?></label><label>Brend<select name="brand_id" required><option value="">Izaberite brend</option><?php foreach($brands as $b):?><option value="<?= $e($b['id']) ?>" <?= (int)($values['brand_id']??0)===(int)$b['id']?'selected':'' ?>><?= $e($b['name']) ?><?= (int)$b['is_active']===0?' (skriven)':'' ?></option><?php endforeach;?></select><?php $error('brand_id');?></label><label>Kategorija<select name="category_id" required><option value="">Izaberite kategoriju</option><?php foreach($categories as $c):?><option value="<?= $e($c['id']) ?>" <?= (int)($values['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= $e($c['name']) ?><?= (int)$c['is_active']===0?' (skrivena)':'' ?></option><?php endforeach;?></select><?php $error('category_id');?></label><label>Model / šifra proizvoda<input name="code" value="<?= $v('code') ?>" maxlength="150" placeholder="Na primer: MSAGBU-12HRFN8"><?php $error('code');?></label><label>Cena<input name="price" value="<?= $v('price') ?>" inputmode="decimal" placeholder="Opciono" min="0" step="0.01"><?php $error('price');?></label><label class="wide">Kratak opis<textarea name="short_description" maxlength="2000" rows="4"><?= $v('short_description') ?></textarea><?php $error('short_description');?></label><label class="wide">Detaljan opis<textarea name="description" maxlength="50000" rows="10"><?= $v('description') ?></textarea><?php $error('description');?></label></div><div class="checks"><label class="check"><input type="checkbox" name="is_featured" value="1" <?= (int)($values['is_featured']??0)===1?'checked':'' ?>> Istaknut proizvod</label><label class="check"><input type="checkbox" name="is_active" value="1" <?= (int)($values['is_active']??0)===1?'checked':'' ?>> Aktivan i vidljiv</label></div></section><button class="button" type="submit">Sačuvaj proizvod</button></form>
